// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human sees and opens drafts"
// Changes: Drafts for the app – open a draft with its project, list a project's drafts, record the viewed revision.
const draftIdInput = (d: { draftId: string }) => ({ draftId: str(obj(d).draftId, 'draftId', 64) })

/** The draft and its project; null when there is no such draft (an ended draft is returned, the UI says so). */
export const getDraftFn = createServerFn()
  .validator(draftIdInput)
  .handler(({ data }) => {
    const store = projectStore()
    const draft = store.getDraft(data.draftId)
    const project = draft && store.getProject(draft.projectId)
    return draft && project ? { project, draft } : null
  })

export const listDraftsFn = createServerFn()
  .validator(idInput)
  .handler(({ data }) => projectStore().listDrafts(data.id))

export const markDraftViewedFn = createServerFn({ method: 'POST' })
  .validator((d: { draftId: string; revision: number }) => ({ ...draftIdInput(d), revision: int(obj(d).revision, 'revision') }))
  .handler(({ data }) => {
    projectStore().markDraftViewed(data.draftId, data.revision)
  })

export const listDraftSnapshotsFn = createServerFn()
  .validator(draftIdInput)
  .handler(({ data }) => projectStore().listDraftSnapshots(data.draftId))

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Draft history"
// Changes: Named snapshot of a draft and restore into a draft; null = no such draft (or snapshot of it); an ended draft
//          is rejected with the reason (shown to the human).
const endedMessage = (state: string) => `Návrh je ukončený (${state === 'adopted' ? 'prevzatý' : 'zahodený'}) – jeho históriu už nemožno meniť.`

export const createDraftSnapshotFn = createServerFn({ method: 'POST' })
  .validator((d: { draftId: string; label: string }) => ({ ...draftIdInput(d), label: str(obj(d).label, 'Popis') }))
  .handler(({ data }) => {
    const result = projectStore().createDraftSnapshot(data.draftId, data.label)
    if (result.status === 'ended') throw new Error(endedMessage(result.draft.state))
    return result.status === 'saved' ? result.snapshot : null
  })

export const restoreDraftSnapshotFn = createServerFn({ method: 'POST' })
  .validator((d: { draftId: string; snapshotId: number }) => ({ ...draftIdInput(d), snapshotId: int(obj(d).snapshotId, 'snapshotId') }))
  .handler(({ data }) => {
    const result = projectStore().restoreDraftSnapshot(data.draftId, data.snapshotId)
    if (result.status === 'ended') throw new Error(endedMessage(result.draft.state))
    return result.status === 'saved' ? result.draft : null
  })
